/**
 * Query-time search plus the write-time index maintenance driven by `search.reindex_requested`.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, subscribe, isEnabled, consumeRateLimit
 */
import { subscribe } from "@/lib/event-bus";
import { isEnabled } from "@/lib/feature-flags";
import { assertCan } from "@/lib/permissions";
import { consumeRateLimit } from "@/lib/rate-limit";
import { isArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import { orgResource } from "./_support";
import type { SearchQueryInput } from "@/schemas/search";
import type { SearchSubjectKind } from "@/server/repositories/search-repository";
import type { Comment } from "@/types/comment";
import type { OrgId, Page } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { Issue } from "@/types/issue";
import type { Actor } from "@/types/member";
import type { Project } from "@/types/project";

export type SearchHit = {
  kind: SearchSubjectKind;
  id: string;
  title: string;
  snippet: string;
  href: string;
};

/** Characters of surrounding context kept on either side of a match. */
const SNIPPET_RADIUS = 60;

/** Token bucket protecting the index from query bursts. */
const SEARCH_QUERY_BUCKET = "search:query";

/** Rows read per page while walking a project's issues and comments. */
const TREE_PAGE_SIZE = 100;

/**
 * Runs a query against the denormalised index. Field-scoped syntax
 * (`status:done`) is an `advanced_search` feature, so a query containing a
 * colon is rejected for plans that do not include it rather than silently
 * being treated as literal text.
 */
export async function search(
  actor: Actor,
  input: SearchQueryInput,
): Promise<Page<SearchHit>> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "issue:read", orgResource(input.orgId));

  const verdict = await consumeRateLimit(input.orgId, SEARCH_QUERY_BUCKET);
  if (!verdict.allowed) {
    throw new Error(
      `Search rate limit reached; try again after ${verdict.resetAt}`,
    );
  }

  const org = await orgRepo.findOrgById(input.orgId);
  const advanced = isEnabled("advanced_search", {
    orgId: input.orgId,
    userId: actor.userId,
    plan: org?.plan ?? "free",
    role: actor.role,
    overrides: org?.settings.enabledFlagOverrides,
  });

  if (input.q.includes(":") && !advanced) {
    throw new Error("Field-scoped search is not included in this plan");
  }

  const page = await searchRepo.searchDocuments(input);

  return {
    items: page.items.map((row) => ({
      kind: row.subjectKind,
      id: row.subjectId,
      title: row.content.split("\n")[0] ?? row.subjectId,
      snippet: snippetAround(row.content, input.q),
      href: hrefFor(row.subjectKind, row.subjectId),
    })),
    nextCursor: page.nextCursor,
    total: page.total,
  };
}

/*
 * Visibility rule: a project is findable while it is live; an issue while the
 * issue and its project are live; a comment while the comment, its issue and
 * that issue's project are all live. Each writer below enforces its part of
 * the rule and removes the document when the rule no longer allows it, so the
 * index holds exactly the findable rows whichever event triggered the write.
 */

async function isIssueVisible(orgId: OrgId, issue: Issue): Promise<boolean> {
  if (isArchived(issue)) return false;
  const project = await projectRepo.findProjectById(orgId, issue.projectId);
  return project !== null && !isArchived(project);
}

async function isCommentVisible(orgId: OrgId, comment: Comment): Promise<boolean> {
  if (isArchived(comment)) return false;
  const issue = await issueRepo.findIssueById(orgId, comment.issueId);
  return issue !== null && (await isIssueVisible(orgId, issue));
}

export async function indexIssue(orgId: OrgId, issue: Issue): Promise<void> {
  if (!(await isIssueVisible(orgId, issue))) {
    await searchRepo.deleteSearchDocument(orgId, "issue", issue.id);
    return;
  }

  await searchRepo.upsertSearchDocument(
    orgId,
    "issue",
    issue.id,
    [issue.title, issue.description ?? ""].join("\n"),
    issue.projectId,
  );
}

export async function indexComment(
  orgId: OrgId,
  comment: Comment,
): Promise<void> {
  if (!(await isCommentVisible(orgId, comment))) {
    await searchRepo.deleteSearchDocument(orgId, "comment", comment.id);
    return;
  }

  await searchRepo.upsertSearchDocument(
    orgId,
    "comment",
    comment.id,
    comment.body,
    null,
  );
}

export async function indexProject(
  orgId: OrgId,
  project: Project,
): Promise<void> {
  if (isArchived(project)) {
    await searchRepo.deleteSearchDocument(orgId, "project", project.id);
    return;
  }

  await searchRepo.upsertSearchDocument(
    orgId,
    "project",
    project.id,
    [project.name, project.description ?? ""].join("\n"),
    project.id,
  );
}

/**
 * Indexes a project and everything under it that the rule allows: the project
 * itself, then each live issue and each live comment on it. Pages through the
 * issues and comments so a project of any size is covered in full. An archived
 * project contributes only the (removed) project document.
 *
 * Returns the number of documents visited.
 */
export async function indexProjectTree(
  orgId: OrgId,
  project: Project,
): Promise<number> {
  await indexProject(orgId, project);
  if (isArchived(project)) return 1;

  let visited = 1;
  let issueCursor: string | null = null;
  do {
    const issuePage = await issueRepo.listIssues({
      orgId,
      projectId: project.id,
      limit: TREE_PAGE_SIZE,
      cursor: issueCursor,
      includeArchived: false,
    });

    for (const issue of issuePage.items) {
      await indexIssue(orgId, issue);
      visited += 1 + (await indexLiveComments(orgId, issue.id));
    }

    issueCursor = issuePage.nextCursor;
  } while (issueCursor !== null);

  return visited;
}

async function indexLiveComments(orgId: OrgId, issueId: Issue["id"]): Promise<number> {
  let visited = 0;
  let commentCursor: string | null = null;
  do {
    const commentPage = await commentRepo.listComments({
      orgId,
      issueId,
      includeArchived: false,
      limit: TREE_PAGE_SIZE,
      cursor: commentCursor,
    });

    for (const comment of commentPage.items) {
      await indexComment(orgId, comment);
      visited += 1;
    }

    commentCursor = commentPage.nextCursor;
  } while (commentCursor !== null);

  return visited;
}

