  return commentService.createComment(tenant.actors.member, { orgId: tenant.org.id, issueId, body, parentId: null, mentionedUserIds: [] });
}

describe("scratch visibility", () => {
  it("1: issue archive removes its comments", async () => {
    const p = await mkProject();
    const i = await mkIssue(p.id, "AAA1 title");
    await mkComment(i.id, "AAA1 comment");
    expect(await count("AAA1", "comment")).toBe(1);
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, i.id);
    expect(await count("AAA1", "issue")).toBe(0);
    expect(await count("AAA1", "comment")).toBe(0);
  });

  it("2+3: project archive hides issues/comments incl. kept ones; later edits/comments stay hidden; restore brings back live only", async () => {
    const p = await mkProject();
    const kept = await mkIssue(p.id, "BBB kept");
    await mkComment(kept.id, "BBB kept comment");
    const gone = await mkIssue(p.id, "BBB gone");
    await mkComment(gone.id, "BBB gone comment");
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, gone.id);

    expect(await count("Proj", "project")).toBeGreaterThan(0);
    await projectService.archiveProject(tenant.actors.admin, { orgId: tenant.org.id, projectId: p.id, archiveIssues: false });
    expect(await count(`Proj${n}`, "project")).toBe(0);
    expect(await count("BBB", "issue")).toBe(0);
    expect(await count("BBB", "comment")).toBe(0);

    // writes while archived stay hidden
    await issueService.updateIssue(tenant.actors.member, { orgId: tenant.org.id, issueId: kept.id, title: "BBB edited" });
    await mkComment(kept.id, "BBB late comment");
    expect(await count("BBB", "issue")).toBe(0);
    expect(await count("BBB", "comment")).toBe(0);

    await projectService.restoreProject(tenant.actors.admin, tenant.org.id, p.id);
    expect(await count(`Proj${n}`, "project")).toBe(1);
    expect(await count("BBB edited", "issue")).toBe(1);
    expect(await count("BBB kept comment", "comment")).toBe(1);
    expect(await count("BBB late comment", "comment")).toBe(1);
    expect(await count("BBB gone", "issue")).toBe(0);
    expect(await count("BBB gone comment", "comment")).toBe(0);
  });

  it("2b: archiving with issues archived cascades; restore keeps them hidden", async () => {
    const p = await mkProject();
    const i = await mkIssue(p.id, "CCC cascade");
    await mkComment(i.id, "CCC cascade comment");
    await projectService.archiveProject(tenant.actors.admin, { orgId: tenant.org.id, projectId: p.id, archiveIssues: true });
    expect(await count("CCC", "issue")).toBe(0);
    expect(await count("CCC", "comment")).toBe(0);
    await projectService.restoreProject(tenant.actors.admin, tenant.org.id, p.id);
    expect(await count("CCC", "issue")).toBe(0);
    expect(await count("CCC", "comment")).toBe(0);
  });

  it("4: rebuild restores only the allowed set, across many pages, and leaves other orgs alone", async () => {
    const other = await createTenant("scratchother", "growth");
    const op = await projectService.createProject(other.actors.admin, {
      orgId: other.org.id, name: "OtherP", slug: "other-p", key: "OTH", description: null,
      visibility: "org", leadId: null, color: "#6366f1", targetDate: null,
    });
    await issueService.createIssue(other.actors.member, issueInput(other.org.id, op.id, { title: "DDD other" }));

    const archivedP = await mkProject();
    await mkIssue(archivedP.id, "DDD in archived project");
    await projectService.archiveProject(tenant.actors.admin, { orgId: tenant.org.id, projectId: archivedP.id, archiveIssues: false });

    const big = await mkProject();
    for (let k = 0; k < 130; k += 1) {
      const iss = await mkIssue(big.id, `DDD bulk ${k}`);
      if (k % 2 === 0) await mkComment(iss.id, `DDD bulk comment ${k}`);
    }
    const archivedIssue = await mkIssue(big.id, "DDD archived bulk");
    await mkComment(archivedIssue.id, "DDD archived bulk comment");
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, archivedIssue.id);

    // Corrupt the index on purpose: insert stale rows the rule forbids.
    const { getDb, searchIndex } = await import("@/server/db");
    getDb().insert(searchIndex).values({ id: "stale-1", orgId: tenant.org.id, subjectKind: "issue", subjectId: "nope-issue", projectId: null, content: "DDD stale", indexedAt: new Date().toISOString() }).run();

    const result = await runSearchReindexJob(tenant.org.id);
    expect(result.failed).toBe(0);

    expect(await count("DDD bulk", "issue")).toBe(130);
    expect(await count("DDD bulk comment", "comment")).toBe(65);
    expect(await count("DDD archived", "issue")).toBe(0);
    expect(await count("DDD archived", "comment")).toBe(0);
    expect(await count("DDD in archived project", "issue")).toBe(0);
    expect(await count("DDD stale", "issue")).toBe(0);
    expect(await count(`Proj${n}`, "project")).toBeGreaterThan(0);

    rateLimitState.allowed = true;
    const otherHits = await searchService.search(other.actors.member, { orgId: other.org.id, q: "DDD other", kinds: ["issue"], limit: 25, cursor: null });
    expect(otherHits.total).toBe(1);
  });
});
